"""Bounded actual held observation collection; functional checks are not release acceptance."""
import argparse,hashlib,itertools,json,subprocess
from pathlib import Path
BEHAVIOR=('bootstrap','construct-good','construct-malformed','construct-missing','explicit-ok','magic-ok','explicit-fault','callback-existing','nested-construct','nested-call-ok','nested-call-fault','callback-deny','callback-throw')
SCOPE=('default','custom-allow','custom-deny','custom-throw','nested','custom-wrapper','foreign-mutation','non-lifo','invalid-token','primary-exception-chain','idempotent-init','standalone')
def require(ok,msg):
 if not ok:raise ValueError(msg)
def validate(body,kind,variant,case,manifest):
 require(kind in ('behavior','scope') and variant in ('baseline','candidate'),'known process kind/variant')
 require(case in (BEHAVIOR if kind=='behavior' else SCOPE),'known case')
 require(kind!='scope' or variant=='candidate','helper candidate only')
 require(type(body) is dict and type(body.get('schema')) is int and body['schema']==1,'body schema')
 require(body.get('case')==case and body.get('application_patch_selected') is False,'case/scope identity')
 require(body.get('probe_sha256')==manifest['files']['behavior.php' if kind=='behavior' else 'scope-probe.php'],'probe identity')
 if kind=='behavior':
  require(body.get('variant')==variant,'variant identity')
  expected={p[len(variant)+1:]:h for p,h in manifest['files'].items() if p.startswith(variant+'/')}
  require(body.get('loaded')==expected,'actual complete included source identities')
  require(type(body.get('runtime',{}).get('php_id')) is int and body['runtime']['php_id']==80306 and body['runtime']['error_reporting']==32767,'native runtime')
  require(body.get('real_transport_coverage') is False and body.get('full_application_bootstrap') is False,'transport scope')
  events=body['events'];phases={x['phase']:x for x in events};require('after-kConf' in phases and 'after-operation' in phases,'event inventory')
  if variant=='candidate':
   for name in ['after-kConf','after-operation']:
    x=phases[name];require(x['marker_seen'] is False and x['wrappers']['http'] is False and x['wrappers']['https'] is False,'candidate outside policy restored')
   if case in ('nested-call-ok','nested-call-fault'):
    x=phases['transport-after-inner'];require(x['marker_seen'] is True and x['wrappers']['http'] is True and x['wrappers']['https'] is True,'inner preserves outer active policy')
   if case=='nested-construct':require(body['nested_results'][0]['wrappers_after']['http'] is True,'nested constructor preserves outer wrappers')
  expected_error='SoapFault' if case in ('construct-malformed','construct-missing','explicit-fault','callback-deny','callback-throw') else None
  require((body['exception']['class'] if body['exception'] else None)==expected_error,'expected actual SOAP outcome')
  if case in ('explicit-ok','magic-ok','nested-call-ok','nested-call-fault'):require(body['result']=={'value':'SYNTHETIC_RESPONSE'},'real response decode')
 else:
  require(body.get('helper_sha256')==manifest['files']['candidate/infra/general/kXmlEntityLoaderPolicy.php'],'actual helper identity')
  require(body.get('php')=='8.3.6' and body.get('native_error_reporting')==32767,'helper runtime')
  states={x['phase']:x for x in body['states']};require('outside-before' in states and 'outside-after' in states,'helper states')
  if case!='standalone':
   require(states['outside-before']['marker'] is False and states['outside-after']['marker'] is False,'helper deny outside')
   if case!='custom-wrapper':require(states['outside-after']['http'] is False and states['outside-after']['https'] is False,'owned wrapper cleanup')
  if case in ('foreign-mutation','non-lifo','invalid-token','primary-exception-chain'):
   require(body['error'] is not None and body['error']['class']=='RuntimeException','failclosed visible exception')
  else:require(body['error'] is None,'unexpected helper error')
  if case=='primary-exception-chain':require(body['error']['previous_class']=='SoapFault' and body['error']['previous_message']=='SYNTHETIC_PRIMARY_SOAPFAULT','original primary cause preserved')
  if case=='custom-wrapper':require(type(body.get('custom_wrapper_hits')) is int and body['custom_wrapper_hits']==1 and states['outside-after']['http'] is True,'preexisting custom wrapper preserved')
  if case=='nested':require(states['after-inner']['marker'] is True and states['after-inner']['http'] is True,'helper nested outer lifetime')
  if case=='custom-deny':require(states['outer']['marker'] is False and states['outer']['prior_callback_active'] is True,'foreign restrictive callback remains active')
  if case=='custom-allow':require(states['outer']['marker'] is True and states['outer']['prior_callback_active'] is True,'foreign allow callback remains active')
  if case=='custom-throw':require(states['outer']['error']['class']=='RuntimeException' and states['outer']['prior_callback_active'] is True,'foreign throwing callback remains active')
  if case=='standalone':require(all(x['prior_callback_active'] is True for x in states.values()),'standalone foreign callback unchanged')
 require(type(body.get('diagnostics')) is list,'diagnostic capture')
 for d in body['diagnostics']:
  require(type(d) is dict and type(d.get('severity')) is int and type(d.get('line')) is int and type(d.get('message')) is str,'typed diagnostic')
 return {'functional_checks':'PASS_BOUNDED_REVISED_CAUSAL_CONTRACT','diagnostic_inventory':'VALIDATED_SEPARATELY'}
"""Candidate diagnostic expectations derive from deny observers and native SOAP boundaries.
This compares expected strings to raw evidence; it never rewrites observed stderr.
"""
import json
DOM='DOMDocument::loadXML(): Failed to load external entity because the resolver function returned null'
def same(a,b):return json.dumps(a,sort_keys=True,separators=(',',':'))==json.dumps(b,sort_keys=True,separators=(',',':'))
def expected(kind,case):
 if kind=='behavior':
  def dom(phase):return {'phase':'observer:'+phase,'severity':2,'message':DOM,'file':'behavior.php','line':28}
  handler=[]
  if case=='callback-deny':handler.append(dom('before-kConf'))
  handler.append(dom('after-kConf'))
  if case not in ('bootstrap','construct-malformed','construct-missing','callback-deny','callback-throw'):handler.append(dom('after-constructor'))
  if case in ('construct-missing','callback-deny'):
   message=('SoapClient::__construct(): I/O warning : failed to load external entity "file:///audit/probe/fixtures/missing.wsdl"' if case=='construct-missing' else 'SoapClient::__construct(): Failed to load external entity because the resolver function returned null')
   handler.append({'phase':'operation:construct','severity':2,'message':message,'file':'candidate/infra/general/kSoapClient.php','line':11})
  handler.append(dom('after-operation'))
  printed=[d for d in handler if d['file']=='behavior.php']
 else:
  dom={'severity':2,'message':DOM,'file':'scope-probe.php','line':42}
  if case=='standalone':handler=[]
  elif case=='custom-wrapper':handler=[dom,{'severity':2,'message':'fopen(http://synthetic-wrapper-control): Failed to open stream: "XmlLifecycleCustomHttp::stream_open" call failed','file':'scope-probe.php','line':93},dom]
  else:handler=[dom]*(3 if case=='custom-deny' else 2)
  printed=handler
 stderr=''.join('Warning: '+d['message']+' in /audit/probe/'+d['file']+' on line '+str(d['line'])+'\n' for d in printed)
 return handler,stderr
def validate_candidate(row):
 handler,stderr=expected(row['kind'],row['case'])
 if not same(row['body']['diagnostics'],handler):raise ValueError('Candidate complete diagnostic inventory differs')
 if type(row['stderr']) is not str or row['stderr']!=stderr:raise ValueError('Candidate complete raw stderr differs')
 return {'handler_count':len(handler),'handler_only_count':sum(d['message'] not in stderr for d in handler),'native_stderr_exact':True,'basis':'policy/fixture-derived complete expectations; raw evidence unchanged'}
"""Offline adjudication of unchanged native records; never rewrites original FAIL reports."""
import hashlib,importlib.util,itertools,json,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent
E=HERE.parents[2]/'doc/php83/evidence/xml-lifecycle-fix'
def module(name):
 spec=importlib.util.spec_from_file_location(name,HERE/(name+'.py'));m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);return m
FUNCTIONAL=module('contract-r2');DIAGNOSTIC=module('diagnostic-contract')
BASE=json.loads((HERE/'baseline-diagnostic-records.json').read_text())
MANIFEST_PIN='c06f54b7dff9035ea1680d96416ab29d7b4669a5dbe26e417bedccf27d742a08'
CHAIN_PIN='5feb006310c2a7da6e790570f71b069738c127bd3374c52aebbf1ee81eed8017'
def same(a,b):return json.dumps(a,sort_keys=True,separators=(',',':'))==json.dumps(b,sort_keys=True,separators=(',',':'))
def require(ok,msg):
 if not ok:raise ValueError(msg)
def reconcile(primary,repeat,chain,manifest):
 require(same(primary,repeat),'independent native records exactly repeated')
 require(primary['manifest_sha256']==MANIFEST_PIN and manifest['phase']=='xml-lifecycle-held-A-r1','frozen stage identity')
 require(primary['status']=='FAIL_RETAINED_OBSERVATIONS','original strict report remains FAIL')
 require(primary['failures']==[['behavior','baseline','callback-throw'],['behavior','candidate','callback-throw']],'only original expected-class failures')
 inventory=[('behavior',v,c) for v,c in itertools.product(('baseline','candidate'),FUNCTIONAL.BEHAVIOR)]+[('scope','candidate',c) for c in FUNCTIONAL.SCOPE]
 rows=primary['records'];require(len(rows)==38 and [(r['kind'],r['variant'],r['case']) for r in rows]==inventory,'exact ordered 38 inventory')
 details=[]
 for row in rows:
  require(type(row['exit']) is int and row['exit']==0,'native integer exit0')
  require(type(row['stdout']) is str and same(json.loads(row['stdout']),row['body']),'parsed body equals raw stdout')
  body=row['body'];FUNCTIONAL.validate(body,row['kind'],row['variant'],row['case'],manifest)
  if row['variant']=='candidate':diags=DIAGNOSTIC.validate_candidate(row)
  else:
   expected=BASE['cases'][row['case']]
   for key in ['diagnostics','runtime','probe_sha256']:require(same(body[key],expected[key]),'unchanged baseline '+key)
   require(type(row['stderr']) is str and row['stderr']==expected['stderr'],'unchanged complete baseline stderr')
   diags={'handler_count':len(body['diagnostics']),'handler_only_count':sum(d['message'] not in row['stderr'] for d in body['diagnostics']),'native_stderr_exact':True,'basis':'unchanged baseline recorded twice'}
  details.append({'kind':row['kind'],'variant':row['variant'],'case':row['case'],'status':'PASS_BOUNDED_CONTRACT_R2','diagnostic_channels':diags})
 require(chain['manifest_sha256']==CHAIN_PIN and chain['product_changed'] is False and chain['acceptance'] is False,'chain instrumentation phase')
 require(len(chain['records'])==2 and [r['variant'] for r in chain['records']]==['baseline','candidate'],'exact causal pair')
 msg="SOAP-ERROR: Parsing WSDL: Couldn't load from 'file:///audit/probe/fixtures/good.wsdl'"
 expected_fault={'class':'SoapFault','message':msg,'chain':[{'class':'SoapFault','message':msg}],'chain_truncated':False}
 thrown={'class':'RuntimeException','message':'SYNTHETIC_LOADER_FAILURE','chain':[{'class':'RuntimeException','message':'SYNTHETIC_LOADER_FAILURE'}],'chain_truncated':False}
 for row in chain['records']:
  require(type(row['exit']) is int and row['exit']==0,'causal native integer exit0')
  require(type(row['stdout']) is str and same(json.loads(row['stdout']),row['body']),'causal body equals raw stdout')
  b=row['body'];require(same(b['exception'],expected_fault),'native SOAP result and complete previous chain')
  require(same(b['resolver_exceptions'],[{'phase':'operation:construct','exception':thrown}]),'actual thrown resolver exception')
  original=next(r['body'] for r in rows if r['kind']=='behavior' and r['variant']==row['variant'] and r['case']=='callback-throw')
  for key in ['loaded','runtime','events','resolver_events','functions','result']:
   require(same(b[key],original[key]),'causal instrumentation unchanged product/runtime/observable '+key)
  require(same(original['exception'],{'class':'SoapFault','message':msg}),'corrected expectation grounded in unchanged primary result')
 return {'status':'PASS_BOUNDED_HELD_CONTRACT_R2','cases':details,'native_primary_processes':38,'native_repeat_processes':38,'native_causal_followup_processes':2,'original_reports_rewritten':False,'original_strict_failures_retained':2,'causal_finding':'native ext/soap yields SoapFault with previous=null for thrown synthetic RuntimeException, identically baseline/candidate','application_acceptance':False,'artifact_selected':False}
def main():
 out=Path(sys.argv[1]);require(not out.exists(),'refuse overwrite')
 primary=json.loads((E/'primary.json').read_text());repeat=json.loads((E/'claude-native-matrix.json').read_text());chain=json.loads((E/'claude-chain-matrix.json').read_text())
 mb=Path('/tmp/php-xml-lifecycle-fix-prep-r1/identities.json').read_bytes();require(hashlib.sha256(mb).hexdigest()==MANIFEST_PIN,'manifest bytes')
 require(hashlib.sha256((E/'primary.json').read_bytes()).hexdigest()==BASE['reference_sha256'],'recorded baseline reference pin')
 require((E/'claude-native.exit').read_text().strip()=='0' and (E/'claude-chain.exit').read_text().strip()=='0','actual CLI terminal exits')
 snapshots=[(E/n).read_bytes() for n in ['primary-runtime-before.json','primary-runtime-after.json','claude-native-before.json','claude-native-after.json','claude-chain-before.json','claude-chain-after.json']]
 require(all(x==snapshots[0] for x in snapshots),'all six runtime snapshots unchanged')
 result=reconcile(primary,repeat,chain,json.loads(mb));result['runtime_snapshot_sha256']=hashlib.sha256(snapshots[0]).hexdigest()
 result['input_sha256']={n:hashlib.sha256((E/n).read_bytes()).hexdigest() for n in ['primary.json','claude-native-matrix.json','claude-chain-matrix.json']}
 result['contract_sha256']={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [HERE/'contract-r2.py',HERE/'diagnostic-contract.py',HERE/'baseline-diagnostic-records.json',Path(__file__)]}
 out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'cases':len(result['cases']),'application_acceptance':False}))
if __name__=='__main__':main()
"""Adversarial offline record guards, not additional native execution."""
import copy,importlib.util,json,pathlib,unittest
HERE=pathlib.Path(__file__).resolve().parent;s=importlib.util.spec_from_file_location('r',HERE/'reconcile.py');r=importlib.util.module_from_spec(s);s.loader.exec_module(r)
E=r.E
P=json.loads((E/'primary.json').read_text());C=json.loads((E/'claude-chain-matrix.json').read_text());M=json.loads(pathlib.Path('/tmp/php-xml-lifecycle-fix-prep-r1/identities.json').read_text())
class Tests(unittest.TestCase):
 def runbad(self,mutate):
  p=copy.deepcopy(P);c=copy.deepcopy(C);m=copy.deepcopy(M);mutate(p,c,m)
  for row in p['records']:
   if 'body' in row:row['stdout']=json.dumps(row['body'])
  for row in c['records']:
   if 'body' in row:row['stdout']=json.dumps(row['body'])
  with self.assertRaises((ValueError,KeyError,TypeError)):r.reconcile(p,copy.deepcopy(p),c,m)
 def candidate(self,p):return next(x for x in p['records'] if x['kind']=='behavior' and x['variant']=='candidate' and x['case']=='construct-good')
 def test_actual38plus2_replay(self):self.assertEqual(r.reconcile(P,P,C,M)['status'],'PASS_BOUNDED_HELD_CONTRACT_R2')
 def test_missing_record(self):self.runbad(lambda p,c,m:p['records'].pop())
 def test_duplicate_case(self):self.runbad(lambda p,c,m:p['records'].__setitem__(1,copy.deepcopy(p['records'][0])))
 def test_boolean_exit(self):self.runbad(lambda p,c,m:p['records'][0].update(exit=False))
 def test_float_exit(self):self.runbad(lambda p,c,m:p['records'][0].update(exit=0.0))
 def test_independent_mismatch(self):
  q=copy.deepcopy(P);q['records'][0]['exit']=2
  with self.assertRaises(ValueError):r.reconcile(P,q,C,M)
 def test_drop_candidate_diagnostic(self):self.runbad(lambda p,c,m:self.candidate(p)['body']['diagnostics'].pop())
 def test_duplicate_candidate_diagnostic(self):self.runbad(lambda p,c,m:self.candidate(p)['body']['diagnostics'].append(copy.deepcopy(self.candidate(p)['body']['diagnostics'][0])))
 def test_unknown_native_warning(self):self.runbad(lambda p,c,m:self.candidate(p).update(stderr=self.candidate(p)['stderr']+'Warning: unexpected\n'))
 def test_drop_native_stderr(self):self.runbad(lambda p,c,m:self.candidate(p).update(stderr=''))
 def test_wrong_diagnostic_line(self):self.runbad(lambda p,c,m:self.candidate(p)['body']['diagnostics'][0].update(line=999))
 def test_bool_diagnostic_severity(self):self.runbad(lambda p,c,m:self.candidate(p)['body']['diagnostics'][0].update(severity=True))
 def test_stderr_list(self):self.runbad(lambda p,c,m:self.candidate(p).update(stderr=[]))
 def test_scope_marker_leak(self):
  def mutate(p,c,m):next(x for x in p['records'] if x['kind']=='scope')['body']['states'][-1]['marker']=True
  self.runbad(mutate)
 def test_baseline_diagnostic_drop(self):self.runbad(lambda p,c,m:p['records'][0]['body']['diagnostics'].pop())
 def test_product_source_drift(self):self.runbad(lambda p,c,m:self.candidate(p)['body']['loaded'].update({'alpha/config/kConf.php':'0'*64}))
 def test_causal_chain_invented(self):self.runbad(lambda p,c,m:c['records'][0]['body']['exception']['chain'].append({'class':'RuntimeException','message':'SYNTHETIC_LOADER_FAILURE'}))
 def test_causal_origin_missing(self):self.runbad(lambda p,c,m:c['records'][0]['body']['resolver_exceptions'].clear())
 def test_causal_truncated(self):self.runbad(lambda p,c,m:c['records'][0]['body']['exception'].update(chain_truncated=True))
 def test_causal_wrong_source(self):self.runbad(lambda p,c,m:c['records'][0]['body']['loaded'].update({'alpha/config/kConf.php':'0'*64}))
 def test_causal_float_exit(self):self.runbad(lambda p,c,m:c['records'][0].update(exit=0.0))
 def test_original_failure_erased(self):self.runbad(lambda p,c,m:p.update(failures=[]))
 def test_changed_helper_hash_manifest(self):self.runbad(lambda p,c,m:m['files'].update({'candidate/infra/general/kXmlEntityLoaderPolicy.php':'0'*64}))
if __name__=='__main__':unittest.main()
